import { motion, useReducedMotion } from "motion/react";
import { useId, useLayoutEffect, useRef } from "react";
import { artemisCx } from "../../../../lib/utils";
const STATUSES = ["All orders", "Paid", "Processing", "Refunded"];
const BUTTON = "art:relative art:z-10 art:inline-flex art:items-center art:justify-center art:whitespace-nowrap art:bg-transparent art:px-3.5 art:py-1.5 art:font-medium art:text-sm art:outline-none art:transition-colors art:duration-150 art:motion-reduce:delay-0 art:motion-reduce:transition-none";
export function OrderStatusTabs({ value, onValueChange, selectionCount, positionSnapshot }: {
    value: string;
    onValueChange: (value: string) => void;
    selectionCount: number;
    positionSnapshot: {
        current: number | null;
    };
}) {
    const layoutId = useId();
    const reduce = useReducedMotion();
    const previous = useRef(value);
    const buttons = useRef(new Map<string, HTMLButtonElement>());
    const indicator = useRef<HTMLSpanElement>(null);
    useLayoutEffect(() => {
        const snapshot = positionSnapshot.current;
        positionSnapshot.current = null;
        const before = previous.current;
        previous.current = value;
        const span = indicator.current;
        if (!reduce || (before === value && snapshot === null) || !span)
            return;
        const from = snapshot ?? buttons.current.get(before)?.getBoundingClientRect().x;
        const to = buttons.current.get(value)?.getBoundingClientRect().x;
        if (from === undefined || to === undefined || from === to)
            return;
        const rect = span.getBoundingClientRect();
        span.style.borderRadius = `${9999 / rect.width * 100}% / ${9999 / rect.height * 100}%`;
        span.style.transformOrigin = "50% 50% 0px";
        span.style.opacity = "1";
        span.style.transform = `translate3d(${from - to}px, 0px, 0px)`;
        const paint = requestAnimationFrame(() => {
            span.style.borderRadius = "9999px";
            span.style.transform = "none";
            span.style.opacity = "";
        });
        return () => { cancelAnimationFrame(paint); };
    }, [value, reduce, selectionCount, positionSnapshot]);
    return (<div className="art:inline-flex art:items-center art:gap-1 art:rounded-full art:p-1 art:bg-muted" role="tablist">
      {STATUSES.map(status => {
            const active = status === value;
            return <div key={status} className="art:relative">
          {active && reduce ? <span ref={indicator} className="art:absolute art:inset-0 art:bg-background art:rounded-full" style={{ borderRadius: 9999 }}/> : active ? <motion.span ref={indicator} layout="position" layoutId={layoutId} className="art:absolute art:inset-0 art:bg-background art:rounded-full" style={{ borderRadius: 9999 }} transition={{ type: "spring", stiffness: 170, damping: 24, mass: 1.2 }}/> : null}
          <button ref={node => { if (node)
                buttons.current.set(status, node);
            else
                buttons.current.delete(status); }} type="button" role="tab" aria-selected={active} className={artemisCx(BUTTON, active ? "art:text-foreground art:delay-100" : "art:text-muted-foreground art:delay-0 art:hover:text-foreground", "art:rounded-full art:min-h-9 art:text-xs")} onClick={() => onValueChange(status)}>{status}</button>
        </div>;
        })}
    </div>);
}

